mapper.select:
SELECT kind, code, label
FROM preference_presets
WHERE kind = #{kind}
  AND code = #{code}
  AND is_active = 1

mapper.delete:
DELETE FROM preference_items
WHERE user_id = #{userId}
  AND kind = #{kind}

mapper.insert:
